<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
import {request} from '../api'
import {entryNames,type Entry} from './entries'
const props=defineProps<{entry:Entry;operation:'copy'|'move';sourceId:string;busy?:boolean;error?:string}>()
const emit=defineEmits<{(e:'confirm',target:{id:string;revision:number;title:string}):void;(e:'cancel'):void}>()
const dialog=ref<HTMLDialogElement|null>(null),search=ref(''),page=ref(1),items=ref<any[]>([]),total=ref(0),selected=ref<any>(null),loading=ref(false),loadError=ref('')
let generation=0,previous:HTMLElement|null=null
async function load(){const g=++generation;loading.value=true;loadError.value='';try{const q=new URLSearchParams({q:search.value,page:String(page.value),exclude_id:props.sourceId});const data=await request('/admin/content/entry-targets?'+q);if(g===generation){items.value=data.items;total.value=data.total}}catch{if(g===generation)loadError.value='文章列表读取失败，请重试'}finally{if(g===generation)loading.value=false}}
watch(page,()=>void load())
onMounted(()=>{previous=document.activeElement as HTMLElement;dialog.value?.showModal();void load()})
onBeforeUnmount(()=>{generation++;dialog.value?.close();previous?.focus()})
function cancel(e?:Event){e?.preventDefault();if(!props.busy)emit('cancel')}
</script>
<template><dialog ref="dialog" class="entry-target-picker" aria-labelledby="entry-target-title" @cancel="cancel"><h2 id="entry-target-title">{{operation==='copy'?'复制卡片到其他文章':'移动卡片到其他文章'}}</h2><p>{{entryNames[entry.kind]}} · {{entry.name}}</p><p v-if="operation==='move'">确认后原文章移除此卡片，卡片 UUID 保持，实际图片不会复制或删除。</p><form @submit.prevent="page=1;load()"><label>搜索文章标题<input v-model="search" maxlength="200" :disabled="busy" autofocus/></label><button :disabled="busy||loading">搜索最近编辑文章</button></form><p role="status">{{error||loadError|| (loading?'正在读取…':'')}}</p><fieldset :disabled="busy||loading"><legend>选择目标文章</legend><label v-for="item in items" :key="item.id" class="target-row"><input v-model="selected" type="radio" name="entry-target" :value="item"/> <span>{{item.title}}<small>{{item.date}} · {{item.travel_enabled?'旅行记录':'日常记录'}} · {{item.status==='published'?'已发布':'草稿'}}</small></span></label><p v-if="!items.length&&!loading">没有可编辑的匹配文章。</p></fieldset><p v-if="selected">已选：{{selected.title}}<strong v-if="selected.status==='published'"> · 确认后会立即更新已发布文章。</strong></p><div class="actions"><button type="button" :disabled="busy||loading||page<=1" @click="page--">上一页</button><span>{{page}}</span><button type="button" :disabled="busy||loading||page*20>=total" @click="page++">下一页</button></div><div class="actions"><button type="button" :disabled="busy||!selected" @click="emit('confirm',selected)">{{operation==='move'?'确认移动':'确认复制'}}</button><button type="button" class="quiet" :disabled="busy" @click="cancel()">取消</button></div></dialog></template>
<style scoped>.entry-target-picker{width:min(560px,calc(100vw - 32px));max-height:85dvh;overflow:auto;box-sizing:border-box;border:1px solid var(--line);border-radius:14px;padding:20px;background:var(--paper);color:var(--ink)}.entry-target-picker::backdrop{background:#0007}.target-row{display:flex;align-items:start;gap:10px;padding:12px 0;overflow-wrap:anywhere}.target-row input{width:auto}.target-row small{display:block;color:var(--muted)}fieldset{border:0;padding:0;min-width:0}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}input[type=text],input:not([type]){width:100%;box-sizing:border-box}</style>
